// codeisland-opencode-plugin — auto-generated by CodeIsland
// version: v9
// OpenCode event forwarding + terminal env injection + permission/question handling
//
// One file serves both OpenCode plugin APIs, picked by capability, not version:
// - OpenCode 1.x calls `server()` and uses the hooks it returns.
// - OpenCode 2 reads `id` + `setup()` and ignores `server()`; it runs plugins in a
//   shared background service, streams `{type, data}` events, and asks questions
//   through forms instead of the question API (#332).
//
// MiMo Code (Xiaomi's OpenCode 1.x fork, also the engine the Xiaomi MiMo desktop
// app runs in its main process) loads this same file through `server()`.
import { connect } from "net";
import { getuid } from "process";
import { execFile, execSync } from "child_process";
import { readFileSync, writeFileSync } from "fs";
import { homedir } from "os";
import { join } from "path";

// The agent this copy reports as. CodeIsland installs the MiMo Code copy with
// this exact line rewritten to "mimo", so sessions, ids and the island's badge
// follow the host that actually loaded the file.
const SOURCE = "opencode";

// Same override the bridge honours (SocketPath.swift).
const SOCKET = process.env.CODEISLAND_SOCKET_PATH || `/tmp/codeisland-${getuid()}.sock`;

function sendToSocket(json) {
  return new Promise((resolve) => {
    try {
      const sock = connect({ path: SOCKET }, () => {
        sock.write(JSON.stringify(json));
        sock.end();
        resolve(true);
      });
      sock.on("error", () => resolve(false));
      sock.setTimeout(3000, () => { sock.destroy(); resolve(false); });
    } catch { resolve(false); }
  });
}

// For blocking requests (permission/question), delegate to the bridge binary which
// uses POSIX sockets. Node.js net module's half-close (sock.end()) causes NWConnection
// to close immediately on macOS, losing the response. The bridge's shutdown(SHUT_WR)
// works correctly with NWConnection.
const BRIDGE_PATH = join(homedir(), ".codeisland", "codeisland-bridge");

function sendAndWaitResponse(json, timeoutMs = 300000, env = undefined) {
  return new Promise((resolve) => {
    try {
      const child = execFile(BRIDGE_PATH, [], {
        timeout: timeoutMs, maxBuffer: 1024 * 1024, ...(env ? { env } : {}),
      }, (error, stdout) => {
        if (error) { resolve(null); return; }
        try { resolve(JSON.parse(stdout)); } catch { resolve(null); }
      });
      child.stdin.write(JSON.stringify(json));
      child.stdin.end();
    } catch { resolve(null); }
  });
}

// ---------------------------------------------------------------------------
// Shared helpers. Named exports exist for tests only: OpenCode 1.x uses the
// default export's server() and OpenCode 2 decodes only `default`.
// ---------------------------------------------------------------------------

export function prettyToolName(name) {
  const raw = String(name || "");
  return raw.charAt(0).toUpperCase() + raw.slice(1);
}

export function mapQuestions(questions) {
  return (questions || []).map(q => ({
    question: q.question || "",
    header: q.header || "",
    options: (q.options || []).map(o => ({ label: o.label, description: o.description })),
    multiSelect: q.multiple || false,
  }));
}

export function permissionInput(action, resources, metadata, message) {
  const items = resources || [];
  const toolInput = { patterns: items, metadata };
  if ((action === "bash" || action === "shell") && items.length > 0) toolInput.command = items.join(" && ");
  if ((action === "edit" || action === "write") && items.length > 0) toolInput.file_path = items[0];
  if (message) toolInput.description = message;
  return toolInput;
}

/// The answer keys CodeIsland uses for AskUserQuestion items: the question
/// text, with `_2`, `_3`… appended to repeats (mirrors AppState). Answers come
/// back as a JSON object whose key order is not guaranteed, so they must be
/// matched by key — never by position.
export function answerKeys(questions) {
  const used = new Set();
  return (questions || []).map((q) => {
    const base = typeof q?.question === "string" ? q.question : "Question";
    let key = base;
    if (used.has(key)) {
      let suffix = 2;
      while (used.has(`${base}_${suffix}`)) suffix += 1;
      key = `${base}_${suffix}`;
    }
    used.add(key);
    return key;
  });
}

/// Selected labels per question, in question order. Multi-select answers use
/// the structured `_codeislandAnswerDetails` when present (labels may contain
/// the ", " CodeIsland joins them with), else the display string.
export function answersFromDecision(questions, decision) {
  const input = decision?.updatedInput || {};
  const answers = input.answers || {};
  const details = input._codeislandAnswerDetails || {};
  const asLabels = (value) => {
    if (Array.isArray(value)) return value.map(String);
    if (value === undefined || value === null || value === "") return [];
    return [String(value)];
  };
  const keys = answerKeys(questions);
  if (!keys.some((key) => key in answers || key in details)) {
    // Answers keyed some other way (e.g. by header): keep the old positional read.
    return keys.map((_, index) => asLabels(Object.values(answers)[index]));
  }
  return keys.map((key) => {
    const detail = details[key];
    if (detail && (Array.isArray(detail.selectedOptions) || detail.customInput)) {
      const picked = Array.isArray(detail.selectedOptions) ? detail.selectedOptions.map(String) : [];
      if (detail.customInput) picked.push(String(detail.customInput));
      return picked;
    }
    return asLabels(answers[key]);
  });
}

/// CodeIsland decision → OpenCode reply verb, or null when there is nothing to send.
export function permissionReplyFromDecision(decision) {
  const behavior = decision?.behavior;
  if (!behavior) return null;
  const hasUpdatedPerms = decision.updatedPermissions != null;
  if (behavior === "always" || (behavior === "allow" && hasUpdatedPerms)) return "always";
  if (behavior === "allow") return "once";
  return "reject";
}

// ---------------------------------------------------------------------------
// OpenCode 2
// ---------------------------------------------------------------------------

/// v2 renamed tools/actions; map the ones CodeIsland renders specially back to
/// the names it knows (e.g. Bash shows the command as the tool description).
const V2_TOOL_NAMES = { shell: "Bash", subagent: "Task", webfetch: "WebFetch", websearch: "WebSearch" };

export function v2ToolName(name) {
  const raw = String(name || "");
  return V2_TOOL_NAMES[raw] || prettyToolName(raw) || "Tool";
}

function v2ToolInput(input) {
  const out = { ...(input || {}) };
  if (out.file_path === undefined) {
    const path = out.filePath ?? out.path;
    if (typeof path === "string") out.file_path = path;
  }
  return out;
}

/// The question tool asks through a form: `metadata.kind === "question"`, one
/// field per question (`title` = header, `description` = question, `type`
/// "multiselect" when multiple). Other forms (MCP elicitation, auth) are not
/// questions CodeIsland can answer, so they map to null.
export function v2QuestionsFromForm(form) {
  if (!form || form.metadata?.kind !== "question" || !Array.isArray(form.fields)) return null;
  const questions = form.fields.map((field) => ({
    question: field.description || field.title || "",
    header: field.title || "",
    options: (field.options || []).map(o => ({ label: o.label ?? o.value, description: o.description })),
    multiSelect: field.type === "multiselect",
  }));
  return questions.length > 0 ? questions : null;
}

/// Answer object for `POST /api/session/:id/form/:formID/reply`: the field key
/// maps to a string (single choice or typed answer) or a string[] (multiselect).
/// Unanswered fields are left out rather than sent empty.
export function v2FormAnswer(form, answerArrays) {
  const answer = {};
  (form?.fields || []).forEach((field, index) => {
    const picked = answerArrays[index] || [];
    if (picked.length === 0) return;
    answer[field.key] = field.type === "multiselect" ? picked : picked.join(", ");
  });
  return answer;
}

const V2_REPLY_EVENTS = new Set(["permission.replied", "form.replied", "form.cancelled"]);

/// Stateful v2 event → CodeIsland hook mapping. No I/O: `base(sessionId, extra)`
/// supplies the transport fields. Returns the payload to send, or null.
export function createV2Mapper(base) {
  const sessions = new Map();
  const cwdBySession = new Map();
  const toolNames = new Map();

  const sid = (id) => `${SOURCE}-${String(id || "")}`;
  const session = (id) => {
    if (!sessions.has(id)) sessions.set(id, { lastAssistantText: "", pendingTitle: null });
    return sessions.get(id);
  };
  const cwdFor = (id) => cwdBySession.get(id) || "";
  const setCwd = (id, dir) => { if (id && dir) cwdBySession.set(id, dir); };
  const isPlaceholderTitle = (title) => !title || /^New session/i.test(title);
  const remember = (map, key, value) => {
    map.set(key, value);
    if (map.size > 500) map.delete(map.keys().next().value);
  };

  function map(event) {
    const t = event?.type;
    const d = event?.data || {};
    const id = d.sessionID;

    switch (t) {
      case "session.created": {
        if (!id) return null;
        setCwd(id, d.location?.directory);
        if (!isPlaceholderTitle(d.title)) session(id).pendingTitle = d.title;
        return base(sid(id), { hook_event_name: "SessionStart", cwd: cwdFor(id) });
      }
      case "session.moved":
        setCwd(id, d.location?.directory);
        return null;
      case "session.renamed":
        if (id && !isPlaceholderTitle(d.title)) session(id).pendingTitle = d.title;
        return null;
      case "session.deleted":
        if (!id) return null;
        sessions.delete(id);
        cwdBySession.delete(id);
        return base(sid(id), { hook_event_name: "SessionEnd" });
      case "session.inbox.enqueued": {
        if (!id || d.item?.type !== "user") return null;
        const prompt = d.item.payload?.text || "";
        session(id).lastAssistantText = "";
        return base(sid(id), { hook_event_name: "UserPromptSubmit", cwd: cwdFor(id), ...(prompt ? { prompt } : {}) });
      }
      case "session.status": {
        if (!id) return null;
        const type = d.status?.type;
        if (type === "busy" || type === "retry") {
          return base(sid(id), { hook_event_name: "UserPromptSubmit", cwd: cwdFor(id) });
        }
        if (type === "idle") {
          const s = session(id);
          const extra = { hook_event_name: "Stop", cwd: cwdFor(id), last_assistant_message: s.lastAssistantText || undefined };
          if (s.pendingTitle) { extra.codex_title = s.pendingTitle; s.pendingTitle = null; }
          return base(sid(id), extra);
        }
        return null;
      }
      case "session.text.ended":
        if (id && d.text) session(id).lastAssistantText = d.text;
        return null;
      case "session.tool.input.started":
        // The only event that names the tool; called/success/failed carry the id.
        if (id && d.id) remember(toolNames, `${id}:${d.id}`, v2ToolName(d.name));
        return null;
      case "session.tool.called":
        if (!id) return null;
        return base(sid(id), {
          hook_event_name: "PreToolUse", cwd: cwdFor(id),
          tool_name: toolNames.get(`${id}:${d.id}`) || "Tool", tool_input: v2ToolInput(d.input),
        });
      case "session.tool.success":
      case "session.tool.failed":
        if (!id) return null;
        return base(sid(id), {
          hook_event_name: t === "session.tool.success" ? "PostToolUse" : "PostToolUseFailure",
          cwd: cwdFor(id), tool_name: toolNames.get(`${id}:${d.id}`) || "Tool",
        });
      case "session.compaction.started":
        if (!id) return null;
        return base(sid(id), { hook_event_name: "PreCompact", cwd: cwdFor(id) });
      case "permission.asked":
        if (!id || !d.id) return null;
        return base(sid(id), {
          hook_event_name: "PermissionRequest", cwd: cwdFor(id),
          tool_name: v2ToolName(d.action),
          tool_input: permissionInput(d.action, d.resources, d.metadata, d.message),
          _opencode_request_id: d.id, _opencode_session_id: id,
        });
      case "form.created": {
        const form = d.form;
        const questions = v2QuestionsFromForm(form);
        if (!questions || !form.id || !form.sessionID) return null;
        return base(sid(form.sessionID), {
          hook_event_name: "PermissionRequest", cwd: cwdFor(form.sessionID),
          tool_name: "AskUserQuestion", tool_input: { questions },
          _opencode_request_id: form.id, _opencode_session_id: form.sessionID, _opencode_form: form,
        });
      }
      case "permission.replied":
      case "form.replied":
      case "form.cancelled":
        if (!id) return null;
        return base(sid(id), { hook_event_name: "PostToolUse", cwd: cwdFor(id) });
      default:
        return null;
    }
  }

  /// Sessions created before this plugin instance started never send
  /// `session.created` here; their directory/title come from a lookup.
  map.knows = (id) => cwdBySession.has(id);
  map.adopt = (id, info) => {
    setCwd(id, info?.location?.directory);
    if (!isPlaceholderTitle(info?.title)) session(id).pendingTitle = info.title;
  };
  return map;
}

/// The session an event belongs to, for the lookup above.
function v2EventSessionId(event) {
  return event?.data?.sessionID || event?.data?.form?.sessionID;
}

/// Event ids already handled in this process. OpenCode 2 loads the plugin once
/// per location, and events without a location reach every instance — the
/// first instance to see an event claims it so a permission is never asked twice.
function claimV2Event(eventId) {
  if (!eventId) return true;
  const key = Symbol.for("codeisland.opencode.v2.claimed");
  const claimed = globalThis[key] || (globalThis[key] = new Map());
  if (claimed.has(eventId)) return false;
  claimed.set(eventId, true);
  if (claimed.size > 2000) claimed.delete(claimed.keys().next().value);
  return true;
}

/// Drives one plugin instance: mapping, pending-request suppression, and the
/// blocking round-trips. Transport and replies are injected (tests use fakes).
export function createV2Runtime({ base, send, ask, replyPermission, replyForm, cancelForm, canAnswerForms, lookupSession }) {
  const map = createV2Mapper(base);
  const pendingSessions = new Set();
  const lookedUp = new Set();

  async function adoptUnknownSession(event) {
    const id = v2EventSessionId(event);
    if (!id || !lookupSession || event.type === "session.created" || map.knows(id) || lookedUp.has(id)) return;
    lookedUp.add(id);
    try {
      const result = await lookupSession(id);
      map.adopt(id, result?.data ?? result);
    } catch {}
  }

  async function blocking(mapped, settle) {
    pendingSessions.add(mapped.session_id);
    let response;
    try {
      response = await ask(mapped);
    } finally {
      pendingSessions.delete(mapped.session_id);
    }
    const decision = response?.hookSpecificOutput?.decision;
    if (decision) await settle(decision);
  }

  return async function handle(event) {
    if (!claimV2Event(event?.id)) return;
    await adoptUnknownSession(event);
    const mapped = map(event);
    if (!mapped) return;

    if (mapped.hook_event_name === "PermissionRequest" && mapped._opencode_form) {
      const form = mapped._opencode_form;
      const payload = { ...mapped };
      delete payload._opencode_form;
      if (!canAnswerForms()) {
        // No verified route back to this server — show it, answer in the TUI.
        await send({ ...payload, hook_event_name: "Notification", message: payload.tool_input.questions[0]?.question || "Question" });
        return;
      }
      blocking(payload, async (decision) => {
        if (decision.behavior === "deny") {
          await cancelForm(form.sessionID, form.id);
          return;
        }
        const answer = v2FormAnswer(form, answersFromDecision(payload.tool_input.questions, decision));
        await replyForm(form.sessionID, form.id, answer);
      }).catch(() => {});
      return;
    }
    if (mapped.hook_event_name === "PermissionRequest") {
      blocking(mapped, async (decision) => {
        const reply = permissionReplyFromDecision(decision);
        if (!reply) return;
        await replyPermission(mapped._opencode_session_id, mapped._opencode_request_id, reply, decision.reason);
      }).catch(() => {});
      return;
    }
    // Same race guard as v1: while CodeIsland holds a request for this session,
    // unrelated activity must not look like "answered elsewhere". Replies,
    // session start and end always go through.
    if (!V2_REPLY_EVENTS.has(event.type)
        && pendingSessions.has(mapped.session_id)
        && mapped.hook_event_name !== "SessionStart"
        && mapped.hook_event_name !== "SessionEnd") {
      return;
    }
    await send(mapped);
  };
}

/// Terminal hints for a v2 event. OpenCode 2 runs plugins in a server, not in
/// the TUI. The default shared service (`serve --service`) is started by
/// whichever client came first and outlives it, so only app-level hints are
/// meaningful there — a tab, pane or TTY id would point at that first client's
/// tab, not at the session's. Any other server (`serve --stdio` standalone, a
/// hand-run `opencode serve`, one spawned by a harness such as T3 Code) is its
/// launcher's child and keeps the full set.
const APP_LEVEL_ENV_KEYS = ["TERM_PROGRAM", "__CFBundleIdentifier"];
const TAB_LEVEL_ENV_KEYS = [
  "ITERM_SESSION_ID", "TERM_SESSION_ID", "TMUX", "TMUX_PANE", "KITTY_WINDOW_ID",
  "HERDR_ENV", "HERDR_PANE_ID", "HERDR_SOCKET_PATH", "HERDR_BIN_PATH",
];
const TAB_LEVEL_ENV_PREFIXES = ["ZELLIJ", "CMUX_", "WEZTERM_", "SUPERSET_", "ORCA_"];

export function v2IsSharedService(argv) {
  return argv.includes("serve") && argv.includes("--service");
}

export function v2TerminalEnv(env, sharedService) {
  const out = {};
  const keys = sharedService ? APP_LEVEL_ENV_KEYS : [...APP_LEVEL_ENV_KEYS, ...TAB_LEVEL_ENV_KEYS];
  for (const k of keys) { if (env[k]) out[k] = env[k]; }
  return out;
}

/// Environment for the bridge the blocking requests go through: it reads the
/// terminal from its own env, so a shared service hands it the same
/// app-level-only view as the events.
export function v2BridgeEnv(env, sharedService) {
  if (!sharedService) return undefined;
  const out = {};
  for (const [k, v] of Object.entries(env)) {
    if (v === undefined) continue;
    if (TAB_LEVEL_ENV_KEYS.includes(k) || TAB_LEVEL_ENV_PREFIXES.some(p => k.startsWith(p))) continue;
    out[k] = v;
  }
  return out;
}

/// This process's own HTTP endpoint, from the service registration file —
/// accepted only when the file names this very process. Forms have no plugin
/// API in OpenCode 2, so answering a question needs the server's HTTP route.
function v2ServiceEndpoint() {
  try {
    const stateHome = process.env.XDG_STATE_HOME || join(homedir(), ".local", "state");
    const info = JSON.parse(readFileSync(join(stateHome, "opencode", "service.json"), "utf8"));
    if (info?.pid !== process.pid || typeof info.url !== "string") return null;
    return { url: info.url, password: info.password };
  } catch { return null; }
}

async function v2FormRequest(method, path, body) {
  const endpoint = v2ServiceEndpoint();
  if (!endpoint) return false;
  const headers = { "Content-Type": "application/json" };
  if (endpoint.password) {
    headers.Authorization = "Basic " + Buffer.from(`opencode:${endpoint.password}`).toString("base64");
  }
  try {
    const res = await fetch(new URL(path, endpoint.url), {
      method, headers, ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
    return res.ok;
  } catch { return false; }
}

function setupV2(ctx) {
  const sharedService = v2IsSharedService(process.argv);
  const env = v2TerminalEnv(process.env, sharedService);
  const bridgeEnv = v2BridgeEnv(process.env, sharedService);
  // The shared service must never become a session's CLI pid: CodeIsland
  // SIGTERMs a tracked CLI that gets reparented to launchd, which is exactly
  // what this service does when the client that spawned it quits. So no
  // `_ppid`, and the bridge is told not to derive one. Other servers live and
  // die with their launcher and are tracked like 1.x.
  const processFields = sharedService ? { _untracked_process: true } : { _ppid: process.pid };
  const base = (sessionId, extra) => ({
    session_id: sessionId, _source: SOURCE, ...processFields, _env: env, ...extra,
  });
  const handle = createV2Runtime({
    base,
    send: sendToSocket,
    ask: (payload) => sendAndWaitResponse(payload, 300000, bridgeEnv),
    replyPermission: (sessionID, requestID, decision, message) =>
      ctx.permission.reply({ sessionID, requestID, decision, ...(message ? { message } : {}) }).catch(() => {}),
    replyForm: (sessionID, formID, answer) =>
      v2FormRequest("POST", `/api/session/${encodeURIComponent(sessionID)}/form/${encodeURIComponent(formID)}/reply`, { answer }),
    cancelForm: (sessionID, formID) =>
      v2FormRequest("DELETE", `/api/session/${encodeURIComponent(sessionID)}/form/${encodeURIComponent(formID)}`),
    canAnswerForms: () => v2ServiceEndpoint() !== null,
    lookupSession: (sessionID) => ctx.session.get({ sessionID }),
  });

  const controller = new AbortController();
  // setup() is awaited by the host before the plugin counts as loaded, so the
  // stream is consumed in the background and stopped by the cleanup below.
  (async () => {
    try {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        try { await handle(event); } catch {}
      }
    } catch {}
  })();
  return () => controller.abort();
}

// ---------------------------------------------------------------------------
// OpenCode 1.x — v1.3.11+ requires default export with server() entrypoint; v1.4+ requires id field
// ---------------------------------------------------------------------------

export default {
  id: "codeisland",
  setup: setupV2,
  server: async ({ client, serverUrl }) => {
    const pid = process.pid;
    const serverPort = serverUrl ? parseInt(serverUrl.port) || 4096 : 4096;
    const msgRoles = new Map();
    const sessions = new Map();
    const toolNamesByCall = new Map();

    // OpenCode client SDK (_client is @hey-api/client-fetch with non-enumerable methods)
    const heyApi = client?._client;

    function getSession(sid) {
      if (!sessions.has(sid)) sessions.set(sid, { lastUserText: "", lastAssistantText: "" });
      return sessions.get(sid);
    }

    // Terminal environment collection
    const ENV_KEYS = [
      "TERM_PROGRAM", "ITERM_SESSION_ID", "TERM_SESSION_ID",
      "TMUX", "TMUX_PANE", "KITTY_WINDOW_ID", "__CFBundleIdentifier",
      "HERDR_ENV", "HERDR_PANE_ID", "HERDR_SOCKET_PATH", "HERDR_BIN_PATH",
    ];

    let detectedTty = null;
    try {
      let walkPid = process.pid;
      for (let i = 0; i < 8; i++) {
        const info = execSync(`ps -o tty=,ppid= -p ${walkPid}`, { timeout: 1000 }).toString().trim();
        const parts = info.split(/\s+/);
        const tty = parts[0], ppid = parseInt(parts[1]);
        if (tty && tty !== "??" && tty !== "?") { detectedTty = `/dev/${tty}`; break; }
        if (!ppid || ppid <= 1) break;
        walkPid = ppid;
      }
    } catch {}

    function collectEnv() {
      const env = {};
      for (const k of ENV_KEYS) { if (process.env[k]) env[k] = process.env[k]; }
      return env;
    }

    function herdrMetadata(env) {
      const pane = env.HERDR_PANE_ID?.trim();
      const socket = env.HERDR_SOCKET_PATH?.trim();
      if (env.HERDR_ENV !== "1" || !pane || !socket) return {};
      const binary = env.HERDR_BIN_PATH?.trim();
      return {
        _herdr_pane_id: pane,
        _herdr_socket_path: socket,
        ...(binary ? { _herdr_bin_path: binary } : {}),
      };
    }

    // Ghostty tab title (OSC 2)
    const termProg = process.env.TERM_PROGRAM || "";
    const isOsc2Terminal = ["ghostty", "xterm-ghostty"].includes(termProg) && !process.env.TMUX;
    let displayTitle = null;

    function setTabTitle(sessionId, cwd, userText, aiTitle) {
      if (!isOsc2Terminal) return;
      const project = (cwd || process.env.PWD || "session").split("/").pop() || "session";
      const prefix = sessionId.replace(`${SOURCE}-`, "").slice(0, 16);
      if (aiTitle) {
        displayTitle = aiTitle.replace(/\n/g, " ").slice(0, 30);
      } else if (!displayTitle && userText) {
        displayTitle = userText.replace(/\n/g, " ").slice(0, 30);
      }
      const title = displayTitle
        ? `${project} · ${displayTitle} · ${prefix}`
        : `${project} · ${prefix}`;
      const osc = `\x1b]2;${title}\x07`;
      if (detectedTty) {
        try { writeFileSync(detectedTty, osc); } catch {}
      }
    }

    // Base fields for every event
    function sessionKey(sessionId) {
      return String(sessionId || "");
    }

    function islandSessionId(sessionId) {
      return `${SOURCE}-${sessionKey(sessionId)}`;
    }

    function setCwd(sessionId, cwd) {
      if (sessionId && cwd) sessionCwd.set(sessionKey(sessionId), cwd);
    }

    function cwdFor(sessionId) {
      return sessionCwd.get(sessionKey(sessionId)) || process.env.PWD || "";
    }

    function rememberTool(sessionId, callId, name) {
      if (!sessionId || !callId || !name) return;
      toolNamesByCall.set(`${sessionKey(sessionId)}:${callId}`, prettyToolName(name));
      if (toolNamesByCall.size > 200) toolNamesByCall.delete(toolNamesByCall.keys().next().value);
    }

    function rememberedTool(sessionId, callId) {
      return toolNamesByCall.get(`${sessionKey(sessionId)}:${callId}`) || "Tool";
    }

    function base(sessionId, extra) {
      const env = collectEnv();
      return { session_id: sessionId, _source: SOURCE, _ppid: pid,
        _env: env, ...herdrMetadata(env), _tty: detectedTty, _server_port: serverPort, ...extra };
    }

    const sessionCwd = new Map();
    // Sessions with an active pending permission/question request.
    // While pending, suppress non-lifecycle events to prevent CodeIsland's
    // "answered externally" logic from draining the request via race condition.
    const pendingRequestSessions = new Set();

    function mapEvent(ev) {
      const t = ev.type;
      const p = ev.properties || {};

      if (t === "session.created" && p.info) {
        const cwd = p.info.directory || p.info.location?.directory || "";
        setCwd(p.info.id, cwd);
        return base(islandSessionId(p.info.id), { hook_event_name: "SessionStart", cwd });
      }
      if (t === "session.deleted" && p.info) {
        sessions.delete(p.info.id); sessionCwd.delete(sessionKey(p.info.id));
        return base(islandSessionId(p.info.id), { hook_event_name: "SessionEnd" });
      }
      if (t === "session.updated" && p.info) {
        if (p.info.directory || p.info.location?.directory) setCwd(p.info.id, p.info.directory || p.info.location?.directory);
        if (p.info.time?.archived) {
          sessions.delete(p.info.id); sessionCwd.delete(sessionKey(p.info.id));
          return base(islandSessionId(p.info.id), { hook_event_name: "SessionEnd" });
        }
        if (p.info.title && !p.info.title.startsWith("New session")) {
          const s = getSession(p.info.id);
          s.pendingTitle = p.info.title;
          setTabTitle(islandSessionId(p.info.id), cwdFor(p.info.id), null, p.info.title);
        }
        return null;
      }
      if (t === "session.next.moved" && p.sessionID) {
        const cwd = p.location?.directory || "";
        setCwd(p.sessionID, cwd);
        return base(islandSessionId(p.sessionID), { hook_event_name: "SessionStart", cwd });
      }
      if (t === "session.next.prompted" || t === "session.next.prompt.admitted") {
        if (!p.sessionID) return null;
        const cwd = cwdFor(p.sessionID);
        const prompt = p.prompt?.text || p.text || "";
        if (!prompt) return base(islandSessionId(p.sessionID), { hook_event_name: "UserPromptSubmit", cwd });
        getSession(p.sessionID).lastUserText = prompt;
        return base(islandSessionId(p.sessionID), { hook_event_name: "UserPromptSubmit", cwd, prompt });
      }
      if (t === "session.next.text.delta" && p.sessionID) {
        const s = getSession(p.sessionID);
        const key = p.textID || "default";
        s.textParts = s.textParts || new Map();
        s.textParts.set(key, (s.textParts.get(key) || "") + (p.delta || ""));
        s.lastAssistantText = Array.from(s.textParts.values()).join("\n");
        return null;
      }
      if (t === "session.next.text.ended" && p.sessionID) {
        const s = getSession(p.sessionID);
        if (p.text) s.lastAssistantText = p.text;
        return null;
      }
      if (t === "session.next.compaction.started" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PreCompact", cwd: cwdFor(p.sessionID) });
      }
      if (t === "session.next.tool.called" && p.sessionID) {
        const toolName = prettyToolName(p.tool || p.name);
        rememberTool(p.sessionID, p.callID, toolName);
        return base(islandSessionId(p.sessionID), { hook_event_name: "PreToolUse", cwd: cwdFor(p.sessionID), tool_name: toolName,
          tool_input: p.input || {} });
      }
      if (t === "session.next.tool.success" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID),
          tool_name: rememberedTool(p.sessionID, p.callID) });
      }
      if (t === "session.next.tool.failed" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUseFailure", cwd: cwdFor(p.sessionID),
          tool_name: rememberedTool(p.sessionID, p.callID) });
      }
      if (t === "session.status" && p.sessionID) {
        const sid = islandSessionId(p.sessionID);
        const s = getSession(p.sessionID);
        const cwd = cwdFor(p.sessionID);
        if (p.status?.type === "busy" || p.status?.type === "retry") {
          return base(sid, { hook_event_name: "UserPromptSubmit", cwd });
        }
        if (p.status?.type === "idle") {
          const extra = { hook_event_name: "Stop", cwd,
            last_assistant_message: s.lastAssistantText || undefined };
          if (s.pendingTitle) { extra.codex_title = s.pendingTitle; s.pendingTitle = null; }
          return base(sid, extra);
        }
      }
      if (t === "message.updated" && p.info?.id && p.info?.sessionID) {
        msgRoles.set(p.info.id, { role: p.info.role, sessionID: p.info.sessionID });
        if (msgRoles.size > 200) { msgRoles.delete(msgRoles.keys().next().value); }
        return null;
      }
      if (t === "message.part.updated" && p.part?.type === "text" && p.part?.messageID) {
        const meta = msgRoles.get(p.part.messageID);
        if (!meta) return null;
        const s = getSession(meta.sessionID);
        const cwd = cwdFor(meta.sessionID);
        const text = p.part.text || "";
        if (meta.role === "user" && text) {
          s.lastUserText = text;
          return base(islandSessionId(meta.sessionID), {
            hook_event_name: "UserPromptSubmit", cwd, prompt: text });
        }
        if (meta.role === "assistant" && text) { s.lastAssistantText = text; }
        return null;
      }
      if (t === "message.part.updated" && p.part?.type === "tool" && p.part?.sessionID) {
        const sid = islandSessionId(p.part.sessionID);
        const st = p.part.state?.status;
        const cwd = cwdFor(p.part.sessionID);
        const toolName = prettyToolName(p.part.tool || p.part.name);
        if (st === "running" || st === "pending") {
          return base(sid, { hook_event_name: "PreToolUse", cwd, tool_name: toolName,
            tool_input: p.part.state?.input || {} });
        }
        if (st === "completed" || st === "error") {
          return base(sid, { hook_event_name: "PostToolUse", cwd, tool_name: toolName });
        }
      }
      if (t === "permission.asked" && p.id && p.sessionID) {
        const toolName = prettyToolName(p.permission);
        const toolInput = permissionInput(p.permission, p.patterns, p.metadata);
        return base(islandSessionId(p.sessionID), { hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID), tool_name: toolName,
          tool_input: toolInput, _opencode_request_id: p.id });
      }
      if (t === "permission.replied" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse",
          cwd: cwdFor(p.sessionID) });
      }
      if (t === "permission.v2.asked" && p.id && p.sessionID) {
        const toolInput = permissionInput(p.action, p.resources, p.metadata);
        return base(islandSessionId(p.sessionID), { hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID), tool_name: prettyToolName(p.action),
          tool_input: toolInput, _opencode_request_id: p.id });
      }
      if (t === "permission.v2.replied" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID) });
      }
      if (t === "question.asked" && p.id && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID), tool_name: "AskUserQuestion",
          tool_input: { questions: mapQuestions(p.questions) }, _opencode_request_id: p.id });
      }
      if ((t === "question.replied" || t === "question.rejected") && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse",
          cwd: cwdFor(p.sessionID) });
      }
      if (t === "question.v2.asked" && p.id && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID), tool_name: "AskUserQuestion",
          tool_input: { questions: mapQuestions(p.questions) }, _opencode_request_id: p.id });
      }
      if ((t === "question.v2.replied" || t === "question.v2.rejected") && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID) });
      }
      return null;
    }

    // Reply to OpenCode via client SDK (_client.request), falling back to HTTP
    async function replyQuestion(requestId, answers) {
      try {
        if (typeof heyApi?.request === "function") {
          await heyApi.request({ method: "POST", url: "/question/{requestID}/reply",
            path: { requestID: requestId }, body: { answers } });
          return;
        }
      } catch {}
      // HTTP fallback for older OpenCode versions without _client.request
      try {
        await fetch(`http://localhost:${serverPort}/question/${requestId}/reply`, {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ answers }),
        });
      } catch {}
    }

    async function rejectQuestion(requestId) {
      try {
        if (typeof heyApi?.request === "function") {
          await heyApi.request({ method: "POST", url: "/question/{requestID}/reject",
            path: { requestID: requestId } });
          return;
        }
      } catch {}
      try {
        await fetch(`http://localhost:${serverPort}/question/${requestId}/reject`, {
          method: "POST", headers: { "Content-Type": "application/json" },
        });
      } catch {}
    }

    async function replyPermission(requestId, reply, reason) {
      try {
        if (typeof heyApi?.request === "function") {
          await heyApi.request({ method: "POST", url: "/permission/{requestID}/reply",
            path: { requestID: requestId }, body: { reply, message: reason } });
          return;
        }
      } catch {}
      try {
        await fetch(`http://localhost:${serverPort}/permission/${requestId}/reply`, {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ reply, message: reason }),
        });
      } catch {}
    }

    async function handlePermissionReply(mapped) {
      const requestId = mapped._opencode_request_id;
      pendingRequestSessions.add(mapped.session_id);
      let response;
      try {
        response = await sendAndWaitResponse(mapped);
      } finally {
        pendingRequestSessions.delete(mapped.session_id);
      }
      const decision = response?.hookSpecificOutput?.decision;
      const reply = permissionReplyFromDecision(decision);
      if (!reply) return;
      await replyPermission(requestId, reply, decision.reason);
    }

    async function handleQuestionReply(mapped) {
      const requestId = mapped._opencode_request_id;
      pendingRequestSessions.add(mapped.session_id);
      let response;
      try {
        response = await sendAndWaitResponse(mapped);
      } finally {
        pendingRequestSessions.delete(mapped.session_id);
      }
      if (!response) return;
      const decision = response?.hookSpecificOutput?.decision;
      if (!decision) return;
      // Skip denied questions (user clicked Skip)
      if (decision.behavior === "deny") {
        await rejectQuestion(requestId);
        return;
      }
      if (!decision?.updatedInput?.answers) return;
      // OpenCode expects one string[] of selected labels per question, in
      // question order — matched by answer key, not by JSON key order.
      await replyQuestion(requestId, answersFromDecision(mapped.tool_input.questions, decision));
    }

    return {
      "event": async ({ event }) => {
        // Reply events (permission.replied, question.replied/rejected) indicate the
        // request was answered externally (e.g. user replied in terminal). These must
        // always flow through so CodeIsland can dismiss the stale approval/question card.
        const isReplyEvent = event.type === "permission.replied"
          || event.type === "question.replied"
          || event.type === "question.rejected";

        const mapped = mapEvent(event);
        if (!mapped) return;
        if (mapped.hook_event_name === "SessionStart") {
          setTabTitle(mapped.session_id, mapped.cwd, null);
        } else if (mapped.hook_event_name === "UserPromptSubmit" && mapped.prompt) {
          setTabTitle(mapped.session_id, null, mapped.prompt);
        }
        // Question: held connection, reply via client SDK
        if (mapped.hook_event_name === "PermissionRequest" && mapped.tool_name === "AskUserQuestion") {
          handleQuestionReply(mapped).catch(() => {});
          return;
        }
        // Permission: held connection, reply via client SDK
        if (mapped.hook_event_name === "PermissionRequest") {
          handlePermissionReply(mapped).catch(() => {});
          return;
        }
        // Suppress non-lifecycle events while a permission/question is pending for this
        // session. Without this, concurrent events (PreToolUse, PostToolUse, Stop) trigger
        // CodeIsland's "answered externally" heuristic, which drains the pending request
        // with an auto-deny before the user can click approve.
        // Reply events are exempted — they genuinely indicate external resolution.
        if (!isReplyEvent
            && pendingRequestSessions.has(mapped.session_id)
            && mapped.hook_event_name !== "SessionStart"
            && mapped.hook_event_name !== "SessionEnd") {
          return;
        }
        await sendToSocket(mapped);
      },
      "shell.env": async (input, output) => {
        for (const v of ["TERM_PROGRAM","ITERM_SESSION_ID","TERM_SESSION_ID",
          "TMUX","TMUX_PANE","KITTY_WINDOW_ID","__CFBundleIdentifier"]) {
          if (process.env[v]) output.env["_CI_" + v] = process.env[v];
        }
      },
    };
  },
};
